import 'package:stash/stash_api.dart';
import 'package:stash_hive/stash_hive.dart';

void main() async {
  final store = await newHiveDefaultVaultStore(path: Directory.systemTemp.path);
  final vault = await store.vault<Task>(name: 'vault', fromEncodable: (json) => Task.fromJson(json));
}
